WITH kept_keys AS (SELECT country FROM customers EXCEPT ALL SELECT country FROM customers WHERE age = 58), reconciled AS (SELECT s.* FROM customers s INNER JOIN kept_keys k ON s.country = k.country) SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, city, CASE WHEN age >= 63 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_tier, COUNT(*) FILTER (WHERE city = 'Chiang Mai') AS chiang_mai_rows, COUNT_IF(city = 'Tokyo') AS tokyo_events FROM reconciled GROUP BY DATE_TRUNC('MONTH', signup_date), city, CASE WHEN age >= 63 THEN 'PREMIUM' ELSE 'STANDARD' END;
